function EXTRA(R,ICON){
 /* hook: a motor driving a compressor through V-belts, and the five belts in their grooves */
 ICON.mdDrive=(x,y)=>{const O=MD_open(112,290,96,34,60);
  return `<g transform="translate(${x-190} ${y-85})">${MD_box(0,0,380,170,{fill:'#FFFFFF',st:MD_GREY,sw:3,r:18})}
  <rect x="12" y="118" width="62" height="40" rx="8" fill="${BLU}"/>${MD_T(43,144,'motor',{fs:18,fw:800,a:'middle',fill:'#FFFFFF'})}
  <path d="${O.d}" fill="none" stroke="${MD_RUB}" stroke-width="8"/>${MD_pulley(112,96,34)}${MD_pulley(290,96,60)}
  ${MD_T(360,30,'compressor',{fs:20,fw:800,a:'end',fill:ORG})}</g>`};
 ICON.mdFive=(x,y)=>{const tb=Math.tan(19*Math.PI/180),gw=52,gd=52,bw=gw-2*gd*tb;let d='M0,50';
  for(let i=0;i<5;i++){const cx=70+i*58;d+=` L${cx-gw/2},50 L${cx-bw/2},${50+gd} L${cx+bw/2},${50+gd} L${cx+gw/2},50`}d+=' L352,50 L352,124 L0,124 Z';
  let s=`<path d="${d}" fill="${MD_LIGHT}" stroke="${MD_STEEL}" stroke-width="3" stroke-linejoin="round"/>`;for(let i=0;i<5;i++)s+=MD_vbelt(70+i*58,42,56,40);
  return `<g transform="translate(${x-190} ${y-85})">${MD_box(0,0,380,170,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}<g transform="translate(14 0)">${s}</g>${MD_T(190,155,'five belts, five grooves',{fs:20,fw:800,a:'middle',fill:BLU})}</g>`};
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.mdCords=(x,y)=>{let s=`<rect x="0" y="40" width="420" height="22" fill="${MD_RUB}"/><rect x="0" y="62" width="420" height="26" fill="#59636E"/><rect x="0" y="88" width="420" height="22" fill="${MD_RUB}"/>`;
  for(let i=0;i<14;i++)s+=`<circle cx="${15+i*30}" cy="75" r="10" fill="${MD_CORD}"/>`;
  s+=MD_L(0,75,420,75,GRN,2,'stroke-dasharray="8 6"')+MD_T(0,30,'flat belt, cut across',{fs:24,fw:800,fill:BLU})+MD_T(0,146,'cords on the neutral axis',{fs:24,fw:800,fill:GRN});
  s+=MD_groove(210,190,150,110,{rim:70})+MD_vbelt(210,178,158,92,{ang:38});
  return `<g transform="translate(${x-210} ${y-170})">${s}</g>`};
 ICON.mdOpenDrive=(x,y)=>{const O=MD_open(90,320,150,60,100);
  return `<g transform="translate(${x-210} ${y-160})"><path d="${O.d}" fill="none" stroke="${MD_RUB}" stroke-width="10"/>${MD_poly([O.bot[0],O.bot[1]],ORG,14)}${MD_pulley(90,150,60)}${MD_pulley(320,150,100)}
  ${MD_T(190,20,'T₂ slack',{fs:24,fw:800,a:'middle',fill:MD_GREY})}${MD_T(190,300,'T₁ tight',{fs:26,fw:800,a:'middle',fill:ORG})}</g>`};
 ICON.mdWedge=(x,y)=>{const bt=Math.sin(19*Math.PI/180),bc=Math.cos(19*Math.PI/180);
  return `<g transform="translate(${x-210} ${y-160})">${MD_groove(210,60,200,170,{rim:110})}${MD_vbelt(210,50,206,140,{ang:38})}
  ${MD_arrow(96,170,96+80*bc,170-80*bt,GRN,6,18)}${MD_arrow(324,170,324-80*bc,170-80*bt,GRN,6,18)}${MD_T(210,30,'μ′ = μ / sin β',{fs:28,fw:800,a:'middle',fill:GRN})}
  ${MD_T(210,320,'grips on both sides',{fs:24,fw:800,a:'middle',fill:MD_DARK})}</g>`};
}
